package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.CatalogService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController public class CatalogController {private final CatalogService s;public CatalogController(CatalogService s){this.s=s;}
 @Tag(name="Destinos") @Operation(summary="Listar destinos activos") @GetMapping("/api/Destinos") public Object destinations(){return s.destinations();}@Tag(name="Destinos") @Operation(summary="Crear destino",security=@SecurityRequirement(name="bearerAuth")) @PostMapping("/api/Destinos")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object createDestination(@Valid@RequestBody Requests.Destination r){return Map.of("mensaje","Destino creado correctamente.","destino",s.createDestination(r));}@Tag(name="Destinos") @Operation(summary="Actualizar destino",security=@SecurityRequirement(name="bearerAuth")) @PutMapping("/api/Destinos/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object updateDestination(@PathVariable int id,@Valid@RequestBody Requests.Destination r){return Map.of("mensaje","Destino actualizado correctamente.","destino",s.updateDestination(id,r));}@Tag(name="Destinos") @Operation(summary="Desactivar destino",security=@SecurityRequirement(name="bearerAuth")) @DeleteMapping("/api/Destinos/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disableDestination(@PathVariable int id){s.disableDestination(id);return Map.of("mensaje","Destino desactivado correctamente.");}
 @Tag(name="Hoteles") @Operation(summary="Listar hoteles activos") @GetMapping("/api/Hoteles")public Object hotels(){return s.hotels();}@Tag(name="Hoteles") @Operation(summary="Crear hotel",security=@SecurityRequirement(name="bearerAuth")) @PostMapping("/api/Hoteles")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object createHotel(@Valid@RequestBody Requests.Hotel r){return Map.of("mensaje","Hotel creado correctamente.","hotel",s.createHotel(r));}@Tag(name="Hoteles") @Operation(summary="Actualizar hotel",security=@SecurityRequirement(name="bearerAuth")) @PutMapping("/api/Hoteles/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object updateHotel(@PathVariable int id,@Valid@RequestBody Requests.Hotel r){return Map.of("mensaje","Hotel actualizado correctamente.","hotel",s.updateHotel(id,r));}@Tag(name="Hoteles") @Operation(summary="Desactivar hotel",security=@SecurityRequirement(name="bearerAuth")) @DeleteMapping("/api/Hoteles/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disableHotel(@PathVariable int id){s.disableHotel(id);return Map.of("mensaje","Hotel desactivado correctamente.");}
 @Tag(name="Transportes") @Operation(summary="Listar transportes activos") @GetMapping("/api/Transportes")public Object transports(){return s.transports();}@Tag(name="Transportes") @Operation(summary="Crear transporte",security=@SecurityRequirement(name="bearerAuth")) @PostMapping("/api/Transportes")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object createTransport(@Valid@RequestBody Requests.Transport r){return Map.of("mensaje","Transporte creado correctamente.","transporte",s.createTransport(r));}@Tag(name="Transportes") @Operation(summary="Actualizar transporte",security=@SecurityRequirement(name="bearerAuth")) @PutMapping("/api/Transportes/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object updateTransport(@PathVariable int id,@Valid@RequestBody Requests.Transport r){return Map.of("mensaje","Transporte actualizado correctamente.","transporte",s.updateTransport(id,r));}@Tag(name="Transportes") @Operation(summary="Desactivar transporte",security=@SecurityRequirement(name="bearerAuth")) @DeleteMapping("/api/Transportes/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disableTransport(@PathVariable int id){s.disableTransport(id);return Map.of("mensaje","Transporte desactivado correctamente.");}}
